Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub:__Entity__), (a)-[r:MENTIONS]->(e:__Entity__)
WHERE (
  (
    (toLower(pub.name) CONTAINS 'wired' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'wired'))
    AND
    (toLower(a.name) CONTAINS 'these are our favorite walmart cyber monday deals'
      OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'these are our favorite walmart cyber monday deals'))
  )
  OR
  (
    (toLower(pub.name) CONTAINS 'fortune' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'fortune'))
    AND
    ((toLower(a.name) CONTAINS 'market' AND (toLower(a.name) CONTAINS 'rate' OR toLower(a.name) CONTAINS 'low'))
      OR any(alias IN coalesce(a.aliases, []) WHERE toLower(alias) CONTAINS 'market' AND (toLower(alias) CONTAINS 'rate' OR toLower(alias) CONTAINS 'low')))
  )
)
RETURN DISTINCT a.name AS article, pub.name AS publisher, type(r) AS relationship, e.name AS connected_entity
LIMIT 10
