Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub)
WHERE
  (
    toLower(coalesce(pub.name, '')) CONTAINS 'fortune'
    AND (
      toLower(coalesce(a.published_on, '')) CONTAINS '2023-10-04'
      OR toLower(coalesce(a.published_on, '')) CONTAINS 'october 4, 2023'
      OR toLower(coalesce(a.published_on, '')) CONTAINS 'oct 4, 2023'
    )
  )
  OR
  (
    toLower(coalesce(pub.name, '')) CONTAINS 'techcrunch'
    AND toLower(coalesce(a.name, '')) CONTAINS 'trial'
    AND EXISTS {
      MATCH (a)-[:MENTIONS]->(p:Person)
      WHERE toLower(p.name) CONTAINS 'sam bankman-fried'
        OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'sam bankman-fried')
    }
  )
OPTIONAL MATCH (a)-[r:MENTIONS|PARTICIPATED_IN|SAID]->(x)
RETURN a.name AS title, pub.name AS publisher, a.published_on AS publication_date,
       collect(DISTINCT CASE WHEN x IS NOT NULL THEN {relationship: type(r), entity: x.name} END) AS related_facts
LIMIT 10
