WHERE id(a) <> id(b)
  AND (toLower(coalesce(a.published_on, '')) CONTAINS '2023-10-07' OR toLower(coalesce(a.published_on, '')) CONTAINS 'october 7, 2023')
  AND (toLower(coalesce(a.title, '')) CONTAINS 'mossad' OR toLower(coalesce(a.name, '')) CONTAINS 'mossad')
