      (a)-[:MENTIONS]->(person:Person)
OPTIONAL MATCH (a)-[:MENTIONS|PART_OF]->(t:Topic)
WHERE (toLower(person.name) CONTAINS 'sam bankman-fried' OR any(alias IN coalesce(person.aliases, []) WHERE toLower(alias) CONTAINS 'sam bankman-fried'))
  AND (
    toLower(p.name) CONTAINS 'the verge' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the verge')
    OR toLower(p.name) CONTAINS 'cnbc' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'cnbc' OR toLower(alias) CONTAINS 'world business news leader')
    OR toLower(p.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch')
  )
  AND (
    any(term IN ['withdrawal', 'trading revenue', 'board', 'fraud', 'personal gain', 'enrichment'] WHERE toLower(coalesce(a.title, '')) CONTAINS term OR toLower(coalesce(a.name, '')) CONTAINS term)
    OR any(term IN ['withdrawal', 'trading revenue', 'board', 'fraud', 'personal gain', 'enrichment'] WHERE toLower(coalesce(t.name, '')) CONTAINS term OR any(alias IN coalesce(t.aliases, []) WHERE toLower(alias) CONTAINS term))
  )
RETURN DISTINCT a.title AS title, person.name AS person, p.name AS publisher, 'MENTIONS' AS person_connection, 'PUBLISHED_BY' AS publisher_connection
LIMIT 10
