Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p)
WHERE (
  (toLower(p.name) CONTAINS 'cnbc'
    OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'cnbc' OR toLower(alias) CONTAINS 'world business news leader'))
  OR
  (toLower(p.name) CONTAINS 'techcrunch'
    OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
)
AND EXISTS {
  MATCH (a)-[:MENTIONS]->(s:Person)
  WHERE toLower(s.name) CONTAINS 'sam bankman-fried'
     OR any(alias IN coalesce(s.aliases, []) WHERE toLower(alias) CONTAINS 'sam bankman-fried')
}
AND (
  (
    (toLower(p.name) CONTAINS 'cnbc'
      OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'cnbc' OR toLower(alias) CONTAINS 'world business news leader'))
    AND (
      toLower(a.name) CONTAINS 'board'
      OR toLower(a.name) CONTAINS 'composition'
      OR EXISTS {
        MATCH (a)-[:MENTIONS]->(x:__Entity__)
        WHERE toLower(x.name) CONTAINS 'board'
           OR toLower(x.name) CONTAINS 'composition'
           OR any(alias IN coalesce(x.aliases, []) WHERE toLower(alias) CONTAINS 'board' OR toLower(alias) CONTAINS 'composition')
      }
    )
  )
  OR
  (
    (toLower(p.name) CONTAINS 'techcrunch'
      OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
    AND (
      toLower(a.name) CONTAINS 'fraud'
      OR EXISTS {
        MATCH (a)-[:MENTIONS]->(x:__Entity__)
        WHERE toLower(x.name) CONTAINS 'fraud'
           OR toLower(x.name) CONTAINS 'fraudulent'
           OR any(alias IN coalesce(x.aliases, []) WHERE toLower(alias) CONTAINS 'fraud' OR toLower(alias) CONTAINS 'fraudulent')
      }
    )
  )
)
MATCH (a)-[r]-(e:__Entity__)
RETURN a.name AS article_title, p.name AS publisher,
       collect(DISTINCT {entity: e.name, relationship: type(r)}) AS connected_entities
