OPTIONAL MATCH (a)-[:FROM_CHUNK]->(:Chunk)-[:FROM_DOCUMENT]->(d:Document)
OPTIONAL MATCH (a)-[:PUBLISHED_BY]->(pub:__Entity__)
WITH a, d, pub,
     [toLower(coalesce(a.name, '')), toLower(coalesce(d.title, ''))] +
     [alias IN coalesce(a.aliases, []) | toLower(alias)] AS articleNames
WHERE any(s IN articleNames WHERE s CONTAINS 'chatgpt' AND s CONTAINS 'everything you need to know')
   OR any(s IN articleNames WHERE s CONTAINS 'youtube' AND (s CONTAINS 'trademark' OR s CONTAINS 'copyright'))
   OR any(s IN articleNames WHERE s CONTAINS 'chatgpt' AND (s CONTAINS 'judges' OR s CONTAINS 'judicial office'))
OPTIONAL MATCH (a)-[r]-(e:__Entity__)
RETURN DISTINCT a.name AS article, d.title AS title, a.published_on AS published_on,
       pub.name AS publisher, type(r) AS relationship, e.name AS connected_entity
LIMIT 10
